		outfitID = tonumber(outfitID);
	end
	if type(outfitID) ~= "number" then
		error("Usage: local name, icon = C_TransmogCollection.GetOutfitInfo(outfitID)", 2);
	end

	local outfitInfo = SIRUS_COLLECTION_PLAYER_OUTFITS[outfitID];
	if outfitInfo then
