	for outfitID = 1, MAX_PLAYER_OUTFITS do
		if SIRUS_COLLECTION_PLAYER_OUTFITS[outfitID] then
			outfitIDs[#outfitIDs + 1] = outfitID;
		end
	end

	return outfitIDs;
end

