local function PopulateHelpText(t, helpPrefix)
	local i = 1;
	local text = _G[helpPrefix..i];
	while text do
		table.insert(t, text);
		i = i + 1;
		text = _G[helpPrefix..i];
	end
end

function C_TransmogCollection.GetHelpTextByCategory(category, subCategory)
	local result = {};

	PopulateHelpText(result, "TRANSMOG_HELP_BODY_");

	if category then
		if category < Enum.TransmogCollectionType.Wand then
			if subCategory ~= 5 then
				if category ~= Enum.TransmogCollectionType.Back and category ~= Enum.TransmogCollectionType.Shirt and category ~= Enum.TransmogCollectionType.Tabard then
					PopulateHelpText(result, "TRANSMOG_HELP_CATEGORY_ARMOR_");
				end
			else
				PopulateHelpText(result, "TRANSMOG_HELP_CATEGORY_TMOG_");
			end
		else
			PopulateHelpText(result, "TRANSMOG_HELP_CATEGORY_"..category.."_");
		end
	end

	return table.concat(result, "\n\n");
end

-- FIX ROUND TRANSMOG-41 (corrige round 42 : mauvais emplacement, avant
-- l'initialisation de C_TransmogCollection = {}, causait un crash total au
-- login "attempt to index global 'C_TransmogCollection' (a nil value)").
-- Diagnostic pour trancher OU exactement un item de sac est "perdu" dans le
-- pipeline qui decide s'il apparait comme candidat dans la grille de
-- Transmogrification. BASE_APPEARANCES[categoryID] (utilise par
-- GetCategoryAppearances, donc par self.visualsList) n'est peuple QUE pour
-- les itemModifiedAppearanceID pour lesquels IsKnownItemModifiedAppearance
-- renvoie true -- et cette fonction, pour la plupart des types de source,
-- renvoie true independamment de la collection reelle du joueur (sauf pour
-- le type de source 5, "cache tant que non collectionne"). Ce diagnostic
-- expose, pour un itemID donne, chaque etape : a-t-il une entree dans
-- ITEM_MODIFIED_APPEARANCE_STORAGE, quelle categorie/sous-categorie/emplacement
-- en ressort, son sourceType, si IsKnownItemModifiedAppearance le laisse
-- passer, et s'il est effectivement present dans BASE_APPEARANCES (donc dans
-- le pool de candidats de la grille) au moment de l'appel.
function C_TransmogCollection.DebugItemPipeline(itemID)
	local info = ITEM_MODIFIED_APPEARANCE_STORAGE[itemID];
	if not info then
		return { itemID = itemID, hasStorageEntry = false };
	end

	local categoryID, subCategoryID, equipLocID = GetItemModifiedAppearanceCategory(itemID);
	local appearanceID = info[ITEM_MODIFIED_APPEARANCE_STORAGE_APPERANCEID];
	local sourceType = info[ITEM_MODIFIED_APPEARANCE_STORAGE_SOURCETYPE];
	local classMask = info[ITEM_MODIFIED_APPEARANCE_STORAGE_CLASSMASK];
	local isKnown = IsKnownItemModifiedAppearance(itemID);
	local isUsable = USABLE_APPEARANCES[itemID] or false;
	-- FIX ROUND TRANSMOG-44 : champs bruts supplementaires pour diagnostiquer
	-- les ARMES (categoryID reste 0 pour elles tant qu'on n'a pas de repli
	-- fiable pour classID/subClassID -- ces 2 chaines natives permettront de
	-- construire ce repli au prochain tour si besoin).
	local rawEquipLocStr, rawItemSubType = select(9, C_Item.GetItemInfo(itemID, nil, nil, nil, true));
	local _, _, _, _, _, _, itemSubTypeStr = C_Item.GetItemInfo(itemID, nil, nil, nil, true);

	local inBaseAppearances = false;
	if categoryID and categoryID ~= 0 and BASE_APPEARANCES[categoryID] and appearanceID then
		for i = 1, #BASE_APPEARANCES[categoryID] do
			if BASE_APPEARANCES[categoryID][i] == appearanceID then
				inBaseAppearances = true;
				break;
			end
		end
	end

	return {
		itemID = itemID,
		hasStorageEntry = true,
		categoryID = categoryID,
		subCategoryID = subCategoryID,
		equipLocID = equipLocID,
		appearanceID = appearanceID,
		sourceType = sourceType,
		classMask = classMask,
		isKnown = isKnown,
		isUsable = isUsable,
		inBaseAppearances = inBaseAppearances,
		rawEquipLocStr = rawEquipLocStr,
		itemSubTypeStr = itemSubTypeStr,
	};
end

-- FIX ROUND TRANSMOG-43 : root cause reelle de "5/13 epaulettes, 0 arme"
-- confirmee en comparant avec la reference TransmogUniverse (systeme
-- glisser-deposer independant, fourni par l'utilisateur) : cette derniere
-- ne se soucie JAMAIS de "connu/collectionne" pour decider si un objet de
-- sac est transmogrifiable -- elle verifie uniquement class/InventoryType
-- via item_template, sans distinction de matiere (tissu/cuir/maille/plaque
-- toutes acceptees pour le meme emplacement). Notre pipeline (BASE_APPEARANCES,
-- alimente par BuildTransmogCollection au login) ne retient une apparence
-- QUE si IsKnownItemModifiedAppearance() la laisse passer -- ce qui exclut
-- une partie des objets selon leur sourceType/classe/faction AVANT meme que
-- le matching sac (round 40) ait une chance de s'executer : un objet ne
-- peut jamais s'afficher s'il n'est pas d'abord dans ce pool de candidats.
-- Cette fonction force l'ajout d'un itemID (et son apparence) dans
-- BASE_APPEARANCES independamment du statut "connu", exactement comme la
-- reference le fait en s'appuyant uniquement sur les donnees brutes de
-- l'item. Appelee pour chaque objet reellement present dans les sacs
-- (Custom_Wardrobe.lua:RegisterBagAppearances, avant RefreshVisualsList).
function C_TransmogCollection.RegisterKnownAppearanceForItem(itemID)
	local info = ITEM_MODIFIED_APPEARANCE_STORAGE[itemID];
	if not info then
		return false;
	end

	local categoryID = GetItemModifiedAppearanceCategory(itemID);
	if not categoryID or categoryID == 0 then
		return false;
	end

	local appearanceID = info[ITEM_MODIFIED_APPEARANCE_STORAGE_APPERANCEID];
	if not appearanceID then
		return false;
	end

	USABLE_APPEARANCES[itemID] = true;
	CollectItemAppearance(appearanceID, categoryID);
	return true;
end

function C_TransmogCollection.GetItemVisualID(itemID)
	local sourceInfo = ITEM_MODIFIED_APPEARANCE_STORAGE[itemID];
	if sourceInfo then
		return sourceInfo[ITEM_MODIFIED_APPEARANCE_STORAGE_APPERANCEID];
	end
end

