for itemID, data in pairs(CUSTOM_MODIFIED_APPEARANCES) do
	if not ITEM_MODIFIED_APPEARANCE_STORAGE[itemID] then
		ITEM_MODIFIED_APPEARANCE_STORAGE[itemID] = data;
	end
end

for displayID, itemIDs in pairs(CUSTOM_APPEARANCE_SOURCES_TO_ADD) do
	if not ITEM_APPEARANCE_STORAGE[displayID] then
		ITEM_APPEARANCE_STORAGE[displayID] = {0, {}};
	end
	local sources = ITEM_APPEARANCE_STORAGE[displayID][2];
	for i = 1, #itemIDs do
		local itemID = itemIDs[i];
		local found = false;
		for j = 1, #sources do
			if sources[j] == itemID then found = true; break; end
		end
		if not found then
			table.insert(sources, itemID);
		end
	end
end

